mutants.replacement:
/iPad|iPhone|iPod/.test(navigator.userAgent) &&
	// iPadOS 13+ reports a macOS user agent; the touchscreen is the tell.
	(navigator.userAgent.includes("Mac") && navigator.maxTouchPoints > 1)

organizationTrigger ||
		bindingCompactionTriggerSource(
			{
				thresholdPercent,
				contextLimit: config.context_limit,
			},
			organizationTrigger.trigger,
		) === "organization"

headerText +
		omittedMarker -
		truncateUtf8(body, bodyBudget - byteLength(omittedMarker), {
			keep: "tail",
		})
